content.content:
1	/* ══════════════════════════════════════════════
2	   CMS Landing — Design System Bundle 기반
3	   ══════════════════════════════════════════════
4	   모든 값은 landingTokens.css 번들에서 가져온다.
5	   surface/shape/type/tone/motion 5개 번들 준수.
6	*/
7	
8	/* ── Page ── */
9	
10	.cmsLanding {
11	  min-height: 100%;
12	  width: 100%;
13	  overflow-x: hidden;
14	  background: var(--landing-surface-base);
15	  color: var(--landing-text-secondary);
16	  font-family: var(--landing-type-body-family);
17	  font-size: var(--landing-type-body-size);
18	  font-weight: var(--landing-type-body-weight);
19	  line-height: var(--landing-type-body-lh);
20	}
21	
22	/* Option wrappers act as layout containers — cards provide their own padding */
23	.cmsLanding [role="option"] {
24	  padding: 0;
25	  border-radius: 0;
26	  outline: none;
27	}
28	
29	/* ══════════════════════════════
30	   Shared section header — type 번들
31	   ══════════════════════════════ */
32	
33	.cmsSectionLabel {
34	  /* type-label 번들 */
35	  font-family: var(--landing-type-label-family);
36	  font-size: var(--landing-type-label-size);
37	  font-weight: var(--landing-type-label-weight);
38	  line-height: var(--landing-type-label-lh);
39	  letter-spacing: var(--landing-tracking-widest);
40	  text-transform: uppercase;
41	  color: var(--landing-text-muted);
42	  margin: 0 0 var(--landing-space-gap-row);
43	}
44	
45	.cmsSectionTitle {
46	  /* type-page 번들 */
47	  font-family: var(--landing-type-page-family);
48	  font-size: var(--landing-type-page-size);
49	  font-weight: var(--landing-type-page-weight);
50	  line-height: var(--landing-type-page-lh);
51	  letter-spacing: var(--landing-tracking-snug);
52	  color: var(--landing-text-bright);
53	  margin: 0 0 var(--landing-space-gap-col);
54	  white-space: pre-line;
55	}
56	
57	.cmsSectionDesc {
58	  /* type-body 번들 */
59	  font-family: var(--landing-type-body-family);
60	  font-size: var(--landing-type-body-size);
61	  font-weight: var(--landing-type-body-weight);
62	  line-height: var(--leading-relaxed);
63	  color: var(--landing-text-muted);
64	  margin: 0 0 var(--landing-space-section-sm);
65	  max-width: 560px;
66	  white-space: pre-line;
67	}
68	
69	/* ══════════════════════════════
70	   Hero — type-hero 번들, 극적 여백
71	   ══════════════════════════════ */
72	
73	.cmsHero {
74	  min-height: 85vh;
75	  padding: var(--landing-space-section) var(--landing-space-inline);
76	  padding-top: 20vh;
77	  background: var(--landing-surface-base);
78	  display: flex;
79	  flex-direction: column;
80	  align-items: center;
81	  text-align: center;
82	  /* full-width — max-width 제거 */
83	}
84	
85	.cmsHeroBadge {
86	  /* type-label + shape-xs */
87	  font-family: var(--landing-type-label-family);
88	  font-size: var(--landing-type-label-size);
89	  font-weight: var(--landing-type-label-weight);
90	  line-height: var(--landing-type-label-lh);
91	  letter-spacing: var(--landing-tracking-widest);
92	  text-transform: uppercase;
93	  color: var(--landing-text-muted);
94	  /* surface-outlined */
95	  background: transparent;
96	  border: 1px solid var(--landing-surface-outlined-border);
97	  /* shape-pill (badge 전용) */
98	  border-radius: var(--landing-radius-pill);
99	  padding: var(--landing-shape-xs-py) var(--landing-shape-xs-px);
100	  margin-bottom: var(--space-2xl);
101	  display: inline-flex;
102	  align-items: center;
103	  gap: var(--landing-space-gap-row);
104	}
105	
106	.cmsHeroBadgeDot {
107	  width: 6px;
108	  height: 6px;
109	  border-radius: 50%;
110	  background: var(--landing-tone-success);
111	  display: inline-block;
112	}
113	
114	.cmsHeroTitle {
115	  /* type-hero 번들 — 4축 전부 */
116	  font-family: var(--landing-type-hero-family);
117	  font-size: var(--landing-type-hero-size);
118	  font-weight: var(--landing-type-hero-weight);
119	  line-height: var(--landing-type-hero-lh);
120	  letter-spacing: var(--landing-tracking-tight);
121	  margin: 0 0 var(--space-2xl);
122	  color: var(--landing-text-bright);
123	  max-width: 16ch;
124	  white-space: pre-line;
125	}
126	
127	.cmsHeroSubtitle {
128	  /* type-section 번들 (hero의 부제 — 조연 후퇴) */
129	  font-family: var(--landing-type-section-family);
130	  font-size: var(--landing-type-section-size);
131	  font-weight: var(--landing-type-body-weight);
132	  line-height: var(--leading-relaxed);
133	  color: var(--landing-text-muted);
134	  margin: 0 0 var(--landing-space-block, 48px);
135	  max-width: 52ch;
136	}
137	
138	.cmsHeroActions {
139	  display: flex;
140	  align-items: center;
141	  gap: var(--landing-space-gap-col);
142	}
143	
144	.cmsHeroCta {
145	  /* type-caption + shape-sm + tone-neutral */
146	  font-family: var(--landing-type-caption-family);
147	  font-size: var(--landing-type-caption-size);
148	  font-weight: var(--landing-type-section-weight);
149	  color: var(--landing-tone-neutral-fg);
150	  background: var(--landing-text-bright);
151	  border: none;
152	  border-radius: var(--landing-shape-sm-r);
153	  padding: var(--landing-shape-sm-py) var(--landing-shape-sm-px);
154	  cursor: pointer;
155	  display: inline-flex;
156	  align-items: center;
157	  gap: var(--landing-space-gap-row);
158	  transition: opacity var(--landing-motion-normal-duration) var(--landing-motion-normal-easing);
159	}
160	
161	.cmsHeroCta:hover { opacity: 0.85; }
162	
163	.cmsHeroCtaSecondary {
164	  /* type-caption + shape-sm + surface-outlined */
165	  font-family: var(--landing-type-caption-family);
166	  font-size: var(--landing-type-caption-size);
167	  font-weight: var(--landing-type-body-weight);
168	  color: var(--landing-text-secondary);
169	  background: transparent;
170	  border: 1px solid var(--landing-surface-outlined-border);
171	  border-radius: var(--landing-shape-sm-r);
172	  padding: var(--landing-shape-sm-py) var(--landing-shape-sm-px);
173	  cursor: pointer;
174	  display: inline-flex;
175	  align-items: center;
176	  gap: var(--landing-space-gap-row);
177	  transition: border-color var(--landing-motion-instant-duration) var(--landing-motion-instant-easing),
178	              color var(--landing-motion-instant-duration) var(--landing-motion-instant-easing);
179	}
180	
181	.cmsHeroCtaSecondary:hover {
182	  color: var(--landing-text-primary);
183	  border-color: var(--landing-text-muted);
184	}
185	
186	/* ══════════════════════════════
187	   Manifesto — 3-col, surface-raised
188	   ══════════════════════════════ */
189	
190	.cmsManifesto {
191	  padding: var(--landing-space-section) var(--landing-space-inline);
192	  background: var(--landing-surface-sunken);
193	}
194	
195	.cmsManifesto > .cmsSectionTitle {
196	  max-width: var(--landing-space-content-max);
197	  margin-left: auto;
198	  margin-right: auto;
199	  text-align: center;
200	  margin-bottom: var(--landing-space-section-sm);
201	}
202	
203	.cmsManifestoValues {
204	  max-width: var(--landing-space-content-max);
205	  margin: 0 auto;
206	  display: grid;
207	  grid-template-columns: repeat(3, 1fr);
208	  gap: var(--landing-space-gap-col);
209	}
210	
211	.cmsValueItem {
212	  /* surface 제거 — 에디토리얼 텍스트 블록 */
213	  background: transparent;
214	  border: none;
215	  box-shadow: none;
216	  border-top: var(--landing-rule);
217	  border-radius: 0;
218	  padding: var(--landing-space-gap-col) 0 0;
219	}
220	
221	
222	.cmsValueItemContent {
223	  display: flex;
224	  flex-direction: column;
225	  gap: var(--landing-space-gap-row);
226	}
227	
228	.cmsValueItemIcon {
229	  /* 에디토리얼 섹션 — 아이콘 제거 */
230	  display: none;
231	}
232	
233	.cmsValueItemTitle {
234	  /* type-section 번들 */
235	  font-family: var(--landing-type-section-family);
236	  font-size: var(--landing-type-section-size);
237	  font-weight: var(--landing-type-section-weight);
238	  line-height: var(--landing-type-section-lh);
239	  color: var(--landing-text-bright);
240	  margin: 0;
241	  letter-spacing: var(--landing-tracking-normal);
242	}
243	
244	.cmsValueItemDesc {
245	  /* type-body 번들 */
246	  font-family: var(--landing-type-body-family);
247	  font-size: var(--landing-type-body-size);
248	  font-weight: var(--landing-type-body-weight);
249	  line-height: var(--leading-relaxed);
250	  color: var(--landing-text-secondary);
251	  margin: 0;
252	}
253	
254	/* ══════════════════════════════
255	   Features — 2-col, surface-raised
256	   ══════════════════════════════ */
257	
258	.cmsFeatures {
259	  padding: var(--landing-space-section) var(--landing-space-inline);
260	  background: var(--landing-surface-base);
261	}
262	
263	/* 공통: 센터 정렬 섹션 헤더 (Features, Patterns, Showcase) */
264	.cmsFeatures > .cmsSectionLabel,
265	.cmsFeatures > .cmsSectionTitle,
266	.cmsFeatures > .cmsSectionDesc,
267	.cmsFeatures > .cmsSectionCta,
268	.cmsPatterns > .cmsSectionLabel,
269	.cmsPatterns > .cmsSectionTitle,
270	.cmsPatterns > .cmsSectionDesc,
271	.cmsPatterns > .cmsSectionCta,
272	.cmsShowcase > .cmsSectionLabel,
273	.cmsShowcase > .cmsSectionTitle,
274	.cmsShowcase > .cmsSectionDesc,
275	.cmsShowcase > .cmsSectionCta {
276	  max-width: var(--landing-space-content-max);
277	  margin-left: auto;
278	  margin-right: auto;
279	  text-align: center;
280	}
281	
282	.cmsFeaturesGrid {
283	  max-width: var(--landing-space-content-max);
284	  margin: 0 auto;
285	  display: grid;
286	  grid-template-columns: repeat(3, 1fr);
287	  gap: var(--landing-space-gap-col);
288	}
289	
290	/* 1+3 layout: first feature card (after stat-cards) spans full width */
291	.cmsStatCard + .cmsFeatureCard {
292	  grid-column: 1 / -1;
293	}
294	
295	.cmsFeatureCard {
296	  /* surface-raised 번들 */
297	  background: var(--landing-surface-raised-bg);
298	  border: 1px solid var(--landing-surface-raised-border);
299	  box-shadow: var(--landing-surface-raised-shadow);
300	  /* shape-lg 번들 */
301	  border-radius: var(--landing-shape-lg-r);
302	  padding: var(--landing-shape-lg-py) var(--landing-shape-lg-px);
303	}
304	
305	
306	.cmsFeatureCardIcon {
307	  width: 36px;
308	  height: 36px;
309	  display: flex;
310	  align-items: center;
311	  justify-content: center;
312	  background: var(--landing-tone-neutral-dim);
313	  border-radius: var(--landing-shape-xs-r);
314	  color: var(--landing-text-secondary);
315	  margin-bottom: var(--landing-space-gap-col);
316	}
317	
318	.cmsFeatureCardTitle {
319	  /* type-section 번들 */
320	  font-family: var(--landing-type-section-family);
321	  font-size: var(--landing-type-section-size);
322	  font-weight: var(--landing-type-section-weight);
323	  line-height: var(--landing-type-section-lh);
324	  color: var(--landing-text-bright);
325	  margin: 0 0 var(--space-sm);
326	  letter-spacing: var(--landing-tracking-normal);
327	}
328	
329	.cmsFeatureCardDesc {
330	  /* type-body 번들 */
331	  font-family: var(--landing-type-body-family);
332	  font-size: var(--landing-type-body-size);
333	  font-weight: var(--landing-type-body-weight);
334	  line-height: var(--leading-relaxed);
335	  color: var(--landing-text-secondary);
336	  margin: 0;
337	}
338	
339	/* ══════════════════════════════
340	   Stat Card — surface-outlined, big number
341	   ══════════════════════════════ */
342	
343	.cmsStatCard {
344	  /* surface-outlined 번들 */
345	  background: transparent;
346	  border: 1px solid var(--landing-surface-outlined-border);
347	  /* shape-lg 번들 */
348	  border-radius: var(--landing-shape-lg-r);
349	  padding: var(--landing-shape-lg-py) var(--landing-shape-lg-px);
350	  /* motion-instant hover */
351	  transition: border-color var(--landing-motion-instant-duration) var(--landing-motion-instant-easing);
352	}
353	
354	.cmsStatCard:hover {
355	  border-color: var(--landing-text-muted);
356	}
357	
358	
359	.cmsStatCardContent {
360	  display: flex;
361	  flex-direction: column;
362	  gap: var(--landing-space-gap-row);
363	}
364	
365	.cmsStatCardValue {
366	  /* type-page 번들 (serif, light, large — 숫자 강조) */
367	  font-family: var(--landing-type-page-family);
368	  font-size: var(--landing-type-page-size);
369	  font-weight: var(--landing-type-page-weight);
370	  line-height: var(--landing-type-page-lh);
371	  letter-spacing: var(--type-display-letter-spacing);
372	  color: var(--landing-text-bright);
373	}
374	
375	.cmsStatCardLabel {
376	  /* type-label 번들 (mono, uppercase) */
377	  font-family: var(--landing-type-label-family);
378	  font-size: var(--landing-type-label-size);
379	  font-weight: var(--landing-type-label-weight);
380	  line-height: var(--landing-type-label-lh);
381	  letter-spacing: var(--landing-tracking-widest);
382	  text-transform: uppercase;
383	  color: var(--landing-text-bright);
384	}
385	
386	.cmsStatCardDesc {
387	  /* type-caption 번들 */
388	  font-family: var(--landing-type-caption-family);
389	  font-size: var(--landing-type-caption-size);
390	  font-weight: var(--landing-type-caption-weight);
391	  line-height: var(--landing-type-caption-lh);
392	  color: var(--landing-text-muted);
393	}
394	
395	/* ══════════════════════════════
396	   Section CTA — text link with arrow
397	   ══════════════════════════════ */
398	
399	.cmsSectionCta {
400	  display: flex;
401	  width: fit-content;
402	  margin-left: auto;
403	  margin-right: auto;
404	}
405	
406	
407	.cmsSectionCtaLink {
408	  /* type-caption 번들 */
409	  font-family: var(--landing-type-caption-family);
410	  font-size: var(--landing-type-caption-size);
411	  font-weight: var(--landing-type-caption-weight);
412	  line-height: var(--landing-type-caption-lh);
413	  color: var(--landing-text-muted);
414	  text-decoration: none;
415	  display: inline-flex;
416	  align-items: center;
417	  gap: var(--landing-space-gap-row);
418	  cursor: pointer;
419	  /* motion-instant */
420	  transition: color var(--landing-motion-instant-duration) var(--landing-motion-instant-easing);
421	  margin-bottom: var(--landing-space-gap-col);
422	}
423	
424	.cmsSectionCtaLink:hover {
425	  color: var(--landing-text-primary);
426	}
427	
428	/* ══════════════════════════════
429	   Patterns — 4-col, surface-outlined
430	   ══════════════════════════════ */
431	
432	.cmsPatterns {
433	  padding: var(--landing-space-section) var(--landing-space-inline);
434	  background: var(--landing-surface-sunken);
435	}
436	
437	.cmsPatternsGrid {
438	  max-width: var(--landing-space-content-max);
439	  margin: 0 auto;
440	  display: grid;
441	  grid-template-columns: repeat(4, 1fr);
442	  gap: var(--landing-space-gap-col);
443	}
444	
445	.cmsPattern {
446	  /* surface-outlined 번들 */
447	  background: transparent;
448	  border: 1px solid var(--landing-surface-outlined-border);
449	  /* shape-sm 번들 */
450	  border-radius: var(--landing-shape-sm-r);
451	  padding: var(--landing-shape-sm-py) var(--landing-shape-sm-px);
452	  display: flex;
453	  align-items: center;
454	  gap: var(--landing-space-gap-row);
455	  transition: border-color var(--landing-motion-instant-duration) var(--landing-motion-instant-easing);
456	}
457	
458	.cmsPattern::after { display: none; }
459	
460	.cmsPattern:hover {
461	  border-color: var(--landing-text-muted);
462	}
463	
464	
465	.cmsPatternIcon {
466	  width: 28px;
467	  height: 28px;
468	  display: flex;
469	  align-items: center;
470	  justify-content: center;
471	  background: var(--landing-tone-neutral-dim);
472	  border-radius: var(--landing-shape-xs-r);
473	  color: var(--landing-text-secondary);
474	  flex-shrink: 0;
475	}
476	
477	.cmsPatternName {
478	  /* type-caption 번들 */
479	  font-family: var(--landing-type-caption-family);
480	  font-size: var(--landing-type-caption-size);
481	  font-weight: var(--landing-type-section-weight);
482	  line-height: var(--landing-type-caption-lh);
483	  color: var(--landing-text-bright);
484	}
485	
486	/* ══════════════════════════════
487	   Showcase — 3-col, surface-raised
488	   ══════════════════════════════ */
489	
490	.cmsShowcase {
491	  padding: var(--landing-space-section) var(--landing-space-inline);
492	  background: var(--landing-surface-base);
493	}
494	
495	.cmsShowcaseGrid {
496	  max-width: var(--landing-space-content-max);
497	  margin: 0 auto;
498	  display: grid;
499	  grid-template-columns: repeat(2, 1fr);
500	  gap: var(--landing-space-section-sm) var(--landing-space-gap-col);
501	}
502	
503	.cmsShowcaseItem {
504	  /* surface 제거 — 좌측 accent border 목록 */
505	  background: transparent;
506	  border: none;
507	  box-shadow: none;
508	  border-left: 2px solid var(--landing-surface-outlined-border);
509	  border-radius: 0;
510	  padding: 0 0 0 var(--landing-shape-sm-px);
511	  /* motion-instant */
512	  transition: border-color var(--landing-motion-instant-duration) var(--landing-motion-instant-easing);
513	}
514	
515	.cmsShowcaseItem:hover {
516	  border-left-color: var(--landing-text-muted);
517	}
518	
519	
520	.cmsShowcaseItemContent {
521	  display: flex;
522	  flex-direction: column;
523	  gap: var(--landing-space-gap-row);
524	}
525	
526	.cmsShowcaseItemIcon {
527	  /* 인라인 — 라벨과 같은 행에 배치 (cmsShowcaseItemLabel 앞) */
528	  width: var(--landing-icon-sm, 16px);
529	  height: var(--landing-icon-sm, 16px);
530	  display: inline-flex;
531	  align-items: center;
532	  justify-content: center;
533	  background: transparent;
534	  border-radius: 0;
535	  color: var(--landing-text-muted);
536	  vertical-align: middle;
537	}
538	
539	.cmsShowcaseItemLabel {
540	  /* type-section 번들 */
541	  font-family: var(--landing-type-section-family);
542	  font-size: var(--landing-type-section-size);
543	  font-weight: var(--landing-type-section-weight);
544	  line-height: var(--landing-type-section-lh);
545	  color: var(--landing-text-bright);
546	  letter-spacing: var(--landing-tracking-normal);
547	  /* 아이콘과 인라인 흐름 */
548	  display: inline;
549	}
550	
551	.cmsShowcaseItemDesc {
552	  /* type-caption 번들 */
553	  font-family: var(--landing-type-caption-family);
554	  font-size: var(--landing-type-caption-size);
555	  font-weight: var(--landing-type-caption-weight);
556	  line-height: var(--landing-type-caption-lh);
557	  color: var(--landing-text-muted);
558	}
559	
560	/* ══════════════════════════════
561	   Journal — article list
562	   ══════════════════════════════ */
563	
564	.cmsJournal {
565	  padding: var(--landing-space-section) var(--landing-space-inline);
566	  background: var(--landing-surface-sunken);
567	}
568	
569	.cmsJournal > .cmsSectionTitle {
570	  max-width: var(--landing-space-content-max);
571	  margin-left: auto;
572	  margin-right: auto;
573	  margin-bottom: var(--landing-space-section-sm);
574	}
575	
576	.cmsJournalList {
577	  max-width: var(--landing-space-content-max);
578	  margin: 0 auto;
579	  display: flex;
580	  flex-direction: column;
581	  gap: 0;
582	}
583	
584	/* Featured article (first in list) — surface-raised card treatment */
585	.cmsJournalList > :first-child {
586	  background: var(--landing-surface-raised-bg);
587	  border: 1px solid var(--landing-surface-raised-border);
588	  box-shadow: var(--landing-surface-raised-shadow);
